use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < R : Idx , C : Idx > SparseBitMatrix < R , C > { # [doc = " Creates a new empty sparse bit matrix with no rows or columns."] pub fn new (num_columns : usize) -> Self { Self { num_columns , rows : IndexVec :: new () } } fn ensure_row (& mut self , row : R) -> & mut DenseBitSet < C > { self . rows . get_or_insert_with (row , | | DenseBitSet :: new_empty (self . num_columns)) } # [doc = " Sets the cell at `(row, column)` to true. Put another way, insert"] # [doc = " `column` to the bitset for `row`."] # [doc = ""] # [doc = " Returns `true` if this changed the matrix."] pub fn insert (& mut self , row : R , column : C) -> bool { self . ensure_row (row) . insert (column) } # [doc = " Sets the cell at `(row, column)` to false. Put another way, delete"] # [doc = " `column` from the bitset for `row`. Has no effect if `row` does not"] # [doc = " exist."] # [doc = ""] # [doc = " Returns `true` if this changed the matrix."] pub fn remove (& mut self , row : R , column : C) -> bool { match self . rows . get_mut (row) { Some (Some (row)) => row . remove (column) , _ => false , } } # [doc = " Sets all columns at `row` to false. Has no effect if `row` does"] # [doc = " not exist."] pub fn clear (& mut self , row : R) { if let Some (Some (row)) = self . rows . get_mut (row) { row . clear () ; } } # [doc = " Do the bits from `row` contain `column`? Put another way, is"] # [doc = " the matrix cell at `(row, column)` true?  Put yet another way,"] # [doc = " if the matrix represents (transitive) reachability, can"] # [doc = " `row` reach `column`?"] pub fn contains (& self , row : R , column : C) -> bool { self . row (row) . is_some_and (| r | r . contains (column)) } # [doc = " Adds the bits from row `read` to the bits from row `write`, and"] # [doc = " returns `true` if anything changed."] # [doc = ""] # [doc = " This is used when computing transitive reachability because if"] # [doc = " you have an edge `write -> read`, because in that case"] # [doc = " `write` can reach everything that `read` can (and"] # [doc = " potentially more)."] pub fn union_rows (& mut self , read : R , write : R) -> bool { if read == write || self . row (read) . is_none () { return false ; } self . ensure_row (write) ; if let (Some (read_row) , Some (write_row)) = self . rows . pick2_mut (read , write) { write_row . union (read_row) } else { unreachable ! () } } # [doc = " Insert all bits in the given row."] pub fn insert_all_into_row (& mut self , row : R) { self . ensure_row (row) . insert_all () ; } pub fn rows (& self) -> impl Iterator < Item = R > { self . rows . indices () } # [doc = " Iterates through all the columns set to true in a given row of"] # [doc = " the matrix."] pub fn iter (& self , row : R) -> impl Iterator < Item = C > { self . row (row) . into_iter () . flat_map (| r | r . iter ()) } pub fn row (& self , row : R) -> Option < & DenseBitSet < C > > { self . rows . get (row) ? . as_ref () } # [doc = " Intersects `row` with `set`. `set` can be either `DenseBitSet` or"] # [doc = " `ChunkedBitSet`. Has no effect if `row` does not exist."] # [doc = ""] # [doc = " Returns true if the row was changed."] pub fn intersect_row < Set > (& mut self , row : R , set : & Set) -> bool where DenseBitSet < C > : BitRelations < Set > , { match self . rows . get_mut (row) { Some (Some (row)) => row . intersect (set) , _ => false , } } # [doc = " Subtracts `set` from `row`. `set` can be either `DenseBitSet` or"] # [doc = " `ChunkedBitSet`. Has no effect if `row` does not exist."] # [doc = ""] # [doc = " Returns true if the row was changed."] pub fn subtract_row < Set > (& mut self , row : R , set : & Set) -> bool where DenseBitSet < C > : BitRelations < Set > , { match self . rows . get_mut (row) { Some (Some (row)) => row . subtract (set) , _ => false , } } # [doc = " Unions `row` with `set`. `set` can be either `DenseBitSet` or"] # [doc = " `ChunkedBitSet`."] # [doc = ""] # [doc = " Returns true if the row was changed."] pub fn union_row < Set > (& mut self , row : R , set : & Set) -> bool where DenseBitSet < C > : BitRelations < Set > , { self . ensure_row (row) . union (set) } }
}